t.script:

const POLL_MS = 1500;

// ── Job cards ─────────────────────────
function createCard(filename, container) {
    const card = document.createElement("div");
    card.className = "job-card";
    card.innerHTML = `
        <div class="job-header">
            <span class="job-filename" title="${filename}">${filename}</span>
            <span class="job-status status-uploading">Uploading</span>
        </div>
        <div class="job-progress">
            <span class="spinner"></span>
            <span class="job-progress-text">Sending file…</span>
        </div>`;
    (container || document.getElementById("jobs")).prepend(card);
    return {
        setStatus(label, cls) {
            const s = card.querySelector(".job-status");
            s.textContent = label;
            s.className = `job-status ${cls}`;
        },
        setProgress(text) {
            card.querySelector(".job-progress-text").textContent = text;
        },
        setJobId(id) {
            let el = card.querySelector(".job-id");
            if (!el) {
                el = document.createElement("div");
                el.className = "job-id";
                card.querySelector(".job-header").after(el);
            }
            el.textContent = `Job: ${id}`;
        },
        showResult(json) {
            card.querySelector(".job-progress").remove();
            const link = document.createElement("a");
            link.className = "result-link";
            link.textContent = "View Result →";
            link.href = json.extraction_id
                ? `/email_parser?view=extraction&id=${json.extraction_id}`
                : "/email_parser?view=extractions";
            card.appendChild(link);
        },
        showError(msg) {
            this.setStatus("Error", "status-error");
            card.querySelector(".job-progress-text").textContent = msg;
            card.querySelector(".spinner").remove();
        }
    };
}

async function processFile(file) {
    const ui = createCard(file.name);
    try {
        const form = new FormData();
        form.append("msg_file", file);
        const submitResp = await fetch("/email_parser/submit", {
            method: "POST",
            body: form,
        });
        const submitData = await submitResp.json();
        if (submitData.error) throw new Error(submitData.error);

        const jobId = submitData.id;
        ui.setJobId(jobId);
        ui.setStatus("Pending", "status-pending");
        ui.setProgress("Waiting for result…");

        while (true) {
            await new Promise(r => setTimeout(r, POLL_MS));
            const pollResp = await fetch(`/email_parser/poll/${jobId}`);
            const result   = await pollResp.json();
            if (result.error) throw new Error(result.error);
            if (result.status !== "PENDING") {
                const ok = result.status_code >= 200 && result.status_code < 300;
                ui.setStatus(result.status, ok ? "status-success" : "status-error");
                ui.showResult(result);
                return;
            }
        }
    } catch (err) {
        ui.showError(err.message);
    }
}

// ── Navigation ────────────────────────
document.querySelectorAll(".nav-item[data-view]").forEach(navItem => {
    navItem.addEventListener("click", () => {
        const viewName = navItem.dataset.view;
        document.querySelectorAll(".nav-item[data-view]").forEach(n => n.classList.remove("active"));
        navItem.classList.add("active");
        document.querySelectorAll(".view").forEach(v => v.classList.remove("active"));
        document.getElementById(`view-${viewName}`).classList.add("active");
    });
});

// ── Drop zone ─────────────────────────
const zone  = document.getElementById("drop-zone");
const input = document.getElementById("file-input");

zone.addEventListener("click", () => input.click());
input.addEventListener("change", () => {
    [...input.files].forEach(processFile);
    input.value = "";
});
zone.addEventListener("dragover", e => { e.preventDefault(); zone.classList.add("drag-over"); });
zone.addEventListener("dragleave", () => zone.classList.remove("drag-over"));
zone.addEventListener("drop", e => {
    e.preventDefault();
    zone.classList.remove("drag-over");
    const files = [...e.dataTransfer.files].filter(f => f.name.toLowerCase().endsWith(".msg"));
    if (files.length) files.forEach(processFile);
});

// ── Instruct view ─────────────────────
const instructDrop  = document.getElementById("instruct-drop");
const instructInput = document.getElementById("instruct-file-input");
const instructChips = document.getElementById("instruct-file-chips");
let instructFiles = [];

function renderChips() {
    instructChips.innerHTML = instructFiles.map((f, i) => `
        <span class="file-chip">${String(f.name).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}<button class="file-chip-remove" data-i="${i}">✕</button></span>
    `).join("");
    instructChips.querySelectorAll(".file-chip-remove").forEach(btn => {
        btn.addEventListener("click", () => {
            instructFiles.splice(Number(btn.dataset.i), 1);
            renderChips();
        });
    });
}

instructDrop.addEventListener("click", () => instructInput.click());
instructInput.addEventListener("change", () => {
    instructFiles.push(...instructInput.files);
    instructInput.value = "";
    renderChips();
});
instructDrop.addEventListener("dragover", e => { e.preventDefault(); instructDrop.classList.add("drag-over"); });
instructDrop.addEventListener("dragleave", () => instructDrop.classList.remove("drag-over"));
instructDrop.addEventListener("drop", e => {
    e.preventDefault();
    instructDrop.classList.remove("drag-over");
    instructFiles.push(...e.dataTransfer.files);
    renderChips();
});

document.getElementById("instruct-submit").addEventListener("click", async () => {
    const body = document.getElementById("instruct-body").value.trim();
    if (!body && instructFiles.length === 0) return;

    const form = new FormData();
    form.append("body_content", body);
    instructFiles.forEach(f => form.append("attachments", f));

    const ui = createCard("Instruction", document.getElementById("instruct-jobs"));
    try {
        const submitResp = await fetch("/email_parser/instruct", {
            method: "POST",
            body: form,
        });
        const submitData = await submitResp.json();
        if (submitData.error) throw new Error(submitData.error);

        const jobId = submitData.id;
        ui.setJobId(jobId);
        ui.setStatus("Pending", "status-pending");
        ui.setProgress("Waiting for result…");

        while (true) {
            await new Promise(r => setTimeout(r, POLL_MS));
            const pollResp = await fetch(`/email_parser/poll/${jobId}`);
            const result   = await pollResp.json();
            if (result.error) throw new Error(result.error);
            if (result.status !== "PENDING") {
                const ok = result.status_code >= 200 && result.status_code < 300;
                ui.setStatus(result.status, ok ? "status-success" : "status-error");
                ui.showResult(result);
                return;
            }
        }
    } catch (err) {
        ui.showError(err.message);
    }
});
